INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.ai_model.power_level.explanation', 'pt-PT', 'Mede a capacidade do modelo com base no número de parâmetros (1B, 2B, ...) e na quantização — apenas os pesos. Um valor baixo indica pouca potência, um valor alto muita potência, mas mais potência exige mais VRAM e computação: é preciso uma máquina mais potente.', '2026-10-09T00:00:00Z', 'initial-setup', '2026-10-09T00:00:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
